export const WIDTH=960,HEIGHT=540;
export const CREW=[
 {id:'tony',name:'TONY',full:'Tony Soprano',role:'THE BOSS',weapon:'Bare-knuckle business',special:'BADA BING',description:'a shoulder charge that clears the room.',power:5,speed:176,hp:150,damage:19,reach:78,color:'#e7bb65'},
 {id:'carmela',name:'CARMELA',full:'Carmela Soprano',role:'THE FIRST LADY',weapon:'Vacuum cleaner',special:'SOME PULP',description:'a cordless phone with your name on it.',power:4,speed:200,hp:125,damage:16,reach:107,color:'#ec9d87'},
 {id:'artie',name:'ARTIE',full:'Artie Bucco',role:'THE CHEF',weapon:'Cast-iron hospitality',special:'CHEF’S SPECIAL',description:'a flying skillet, served extra hot.',power:4,speed:216,hp:115,damage:17,reach:88,color:'#b7c9a3'},
 {id:'junior',name:'JUNIOR',full:'Corrado Soprano',role:'THE OLD SCHOOL',weapon:'A little cane discipline',special:'OLD SCHOOL',description:'a spinning cane sweep. Respect your elders.',power:3,speed:164,hp:130,damage:17,reach:119,color:'#a8c4d0'}
];
export const STAGES=[
 {name:'SATRIALE’S',sub:'A beef on the block',boss:'PAULIE',row:1,track:'Pork Store Shuffle',story:'The envelopes are missing. The neighborhood has opinions. Go have a word.'},
 {name:'BADA BING',sub:'Last call for trouble',boss:'SILVIO',row:2,track:'Neon on Route 17',story:'The trail leads to the Bing. Someone has put a price on your evening.'},
 {name:'VESUVIO',sub:'The final course',boss:'CHRISTOPHER',row:3,track:'Table for Trouble',story:'One last sit-down. Clear the street and bring the family business home.'}
];
export const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export class Game {
 constructor(ids=[1],difficulty='normal',seed=1999){this.seed=seed;this.difficulty=difficulty;this.players=ids.map((id,i)=>this.player(id,i));this.stage=0;this.sector=0;this.phase='playing';this.time=0;this.score=0;this.kills=0;this.continues=2;this.enemies=[];this.projectiles=[];this.particles=[];this.pickups=[];this.events=[];this.shake=0;this.camera=0;this.banner=3;this.clear=false;this.spawnWave();}
 random(){this.seed=(Math.imul(this.seed,1664525)+1013904223)>>>0;return this.seed/4294967296;}
 player(id,i){const c=CREW[id];return {id:'p'+i,slot:i,crew:id,x:230+i*90,y:440+i*30,z:0,vz:0,face:1,hp:c.hp,maxHp:c.hp,lives:3,energy:100,cooldown:0,attack:0,attackKind:'hit',attackTotal:.3,invuln:0,stun:0,combo:0,comboTime:0,chain:0,block:false,moving:false,dead:0,dash:0,spin:0};}
 emit(type,data={}){this.events.push({type,...data});}
 spawnWave(){this.clear=false;this.banner=2.5;const n=3+this.sector+(this.players.length-1)*2;for(let i=0;i<n;i++)this.spawnEnemy(i,false);if(this.sector===2)this.spawnEnemy(n,true);this.emit('wave',{stage:this.stage,sector:this.sector});}
 spawnEnemy(i,boss){const hp=(boss?245+this.stage*55:48+this.stage*14+this.sector*8)*(this.players.length===2?1.35:1);this.enemies.push({id:'e'+this.stage+'-'+this.sector+'-'+i,crew:boss?STAGES[this.stage].row:1+(i+this.stage)%3,boss,name:boss?STAGES[this.stage].boss:['ASSOCIATE','COLLECTOR','BUTTON MAN'][i%3],x:this.sector*800+600+i*72,y:385+(i*41)%122,z:0,face:-1,hp,maxHp:hp,cooldown:1+i*.2,wind:0,attack:0,stun:0,invuln:0,dead:0,moving:false,attackKind:'hit',attackTotal:.36,charge:0});}
 startNextStage(){if(this.phase!=='stageclear')return;this.stage++;this.sector=0;this.enemies=[];this.pickups=[];this.projectiles=[];this.camera=0;this.phase='playing';for(const p of this.players){p.x=230+p.slot*90;p.y=445+p.slot*25;p.hp=p.maxHp;p.energy=100;p.lives=Math.max(1,p.lives);p.dead=0;p.z=0;p.invuln=2;}this.spawnWave();}
 continueGame(){if(this.phase!=='gameover'||!this.continues)return false;this.continues--;this.phase='playing';for(const p of this.players){p.lives=3;p.hp=p.maxHp;p.energy=100;p.dead=0;p.invuln=3;p.z=0;p.x=this.sector*800+230;p.y=450;}return true;}
 attack(p,kind){if(p.hp<=0||p.cooldown>0||p.stun>0)return false;const c=CREW[p.crew];if(kind==='special'&&p.energy<35){this.emit('empty',{slot:p.slot});return false;}p.block=false;p.attackKind=kind;p.attackTotal=kind==='kick'?.42:kind==='special'?.58:.28;p.attack=p.attackTotal;p.cooldown=kind==='kick'?.46:kind==='special'?.65:.3;
 if(kind==='special'){p.energy-=35;p.invuln=.65;this.emit('special',{name:c.special,slot:p.slot});if(p.crew===1||p.crew===2){this.projectiles.push({x:p.x+p.face*40,y:p.y,z:78+p.z,vx:p.face*510,life:1.8,owner:p,kind:p.crew===1?'phone':'pan',angle:0,hit:new Set()});}else if(p.crew===0){p.dash=.45;p.dashHit=new Set();}else{p.spin=.52;p.spinHit=new Set();}}else{p.chain=(p.chain+1)%3;const reach=c.reach+(kind==='kick'?24:0);for(const e of this.enemies){if(e.hp<=0)continue;const dx=e.x-p.x;if(Math.abs(e.y-p.y)<30&&Math.abs(dx)<reach&&dx*p.face>-20){const dmg=(kind==='kick'?c.damage*1.35:c.damage)*(p.z>15?1.3:1)*(p.chain===0?1.2:1);this.hurtEnemy(e,dmg,p,kind==='kick'?27:16);}}this.emit('swing',{kind});}return true;}
 hurtEnemy(e,damage,p,force=20){if(e.hp<=0||e.invuln>0)return;e.hp=Math.max(0,e.hp-damage);e.stun=e.boss?.17:.32;e.wind=0;e.invuln=.11;e.x=clamp(e.x+p.face*force,this.sector*800+25,this.sector*800+940);p.combo=p.comboTime>0?p.combo+1:1;p.comboTime=2;p.energy=clamp(p.energy+6,0,100);this.score+=Math.round(damage*4)*(1+Math.floor(p.combo/5));this.shake=Math.max(this.shake,damage>30?8:4);this.burst(e.x,e.y-65,'#f4ce82',10);this.emit('hit',{damage,combo:p.combo});if(e.hp===0){e.dead=.75;this.kills++;this.score+=e.boss?1500:250;this.emit('ko',{boss:e.boss});this.pickups.push({x:e.x,y:e.y,kind:this.kills%3===0?'sandwich':'cash',life:24,bob:this.random()*6});}}
 hurtPlayer(p,e){if(p.hp<=0||p.invuln>0||p.z>24)return;const guarding=p.block&&(e.x-p.x)*p.face>0;let dmg=e.boss?20+this.stage*3:10+this.stage*2;if(guarding)dmg*=.12;p.hp=Math.max(0,p.hp-dmg);p.invuln=guarding?.25:.72;p.stun=guarding?0:.2;p.x=clamp(p.x+e.face*(guarding?4:16),this.sector*800+25,this.sector*800+940);if(!guarding){p.combo=0;this.shake=5;}this.burst(p.x,p.y-65,guarding?'#a2d8e3':'#e69e77',8);this.emit(guarding?'block':'hurt');if(p.hp===0){p.lives--;p.dead=1.8;this.emit('down',{slot:p.slot});}}
 burst(x,y,color,n){for(let i=0;i<n;i++)this.particles.push({x,y,vx:(this.random()-.5)*270,vy:(this.random()-.7)*220,life:.25+this.random()*.2,color});}
 update(dt,inputs=[]){if(this.phase!=='playing')return;dt=clamp(dt,0,.05);this.time+=dt;this.banner=Math.max(0,this.banner-dt);this.shake=Math.max(0,this.shake-dt*25);
 for(const p of this.players){const input=inputs[p.slot]||{};p.cooldown=Math.max(0,p.cooldown-dt);p.attack=Math.max(0,p.attack-dt);p.invuln=Math.max(0,p.invuln-dt);p.stun=Math.max(0,p.stun-dt);p.comboTime=Math.max(0,p.comboTime-dt);if(p.comboTime===0)p.combo=0;p.energy=clamp(p.energy+dt*2,0,100);p.moving=false;if(p.hp<=0){p.dead-=dt;if(p.dead<=0&&p.lives>0){p.hp=p.maxHp;p.invuln=2;p.z=0;p.vz=0;p.energy=Math.max(p.energy,50);}continue;}
 const c=CREW[p.crew];p.block=!!input.block&&p.z===0&&p.attack<=0;p.z+=p.vz*dt;p.vz-=900*dt;if(p.z<=0){p.z=0;p.vz=0;}if(input.jump&&p.z===0&&p.stun<=0&&!p.block){p.vz=350;p.z=1;this.emit('jump');}
 if(p.stun<=0){let dx=input.x||0,dy=input.y||0;const length=Math.hypot(dx,dy);if(length>1){dx/=length;dy/=length;}const speed=c.speed*(p.block?.35:1)*(p.attack>0?.4:1);p.x+=dx*speed*dt;p.y+=dy*speed*.58*dt;p.moving=length>.1;if(dx&&!p.dash)p.face=Math.sign(dx);if(input.special)this.attack(p,'special');else if(input.kick)this.attack(p,'kick');else if(input.hit)this.attack(p,'hit');}
 if(p.dash>0){p.dash-=dt;p.x+=p.face*510*dt;for(const e of this.enemies){if(Math.abs(e.x-p.x)<85&&Math.abs(e.y-p.y)<38&&!p.dashHit.has(e.id)){this.hurtEnemy(e,46,p,48);p.dashHit.add(e.id);}}}if(p.spin>0){p.spin-=dt;for(const e of this.enemies){if(Math.abs(e.x-p.x)<145&&Math.abs(e.y-p.y)<47&&!p.spinHit.has(e.id)){this.hurtEnemy(e,44,p,40);p.spinHit.add(e.id);}}}p.x=clamp(p.x,this.sector*800+25,this.sector*800+940);p.y=clamp(p.y,379,510);
 }
 const alive=this.players.filter(p=>p.hp>0);for(const e of this.enemies){e.attack=Math.max(0,e.attack-dt);e.stun=Math.max(0,e.stun-dt);e.invuln=Math.max(0,e.invuln-dt);e.cooldown=Math.max(0,e.cooldown-dt);e.moving=false;if(e.hp<=0){e.dead-=dt;continue;}if(!alive.length||e.stun>0)continue;const p=alive.reduce((a,b)=>Math.hypot(a.x-e.x,a.y-e.y)<Math.hypot(b.x-e.x,b.y-e.y)?a:b);e.face=p.x<e.x?-1:1;const dx=p.x-e.x,dy=p.y-e.y;
 if(e.wind>0){e.wind-=dt;if(e.wind<=0){e.attack=.32;e.cooldown=e.boss?.65:1.15;if(Math.abs(dx)<86&&Math.abs(dy)<30)this.hurtPlayer(p,e);}continue;}
 if(Math.abs(dx)<70&&Math.abs(dy)<25){if(e.cooldown<=0){e.wind=e.boss?.4:.55;this.emit('wind',{boss:e.boss});}}else{const s=(e.boss?112:84)+this.stage*10;e.x+=Math.sign(dx)*s*dt*(Math.abs(dx)>55?1:0);e.y+=Math.sign(dy)*s*.58*dt*(Math.abs(dy)>9?1:0);e.moving=true;}
 e.x=clamp(e.x,this.sector*800+20,this.sector*800+940);e.y=clamp(e.y,379,510);
 }
 // Separation keeps enemies readable instead of allowing a single overlapping pile.
 for(let i=0;i<this.enemies.length;i++)for(let j=i+1;j<this.enemies.length;j++){const a=this.enemies[i],b=this.enemies[j];if(a.hp>0&&b.hp>0&&Math.abs(a.x-b.x)<27&&Math.abs(a.y-b.y)<19){const d=(a.y<=b.y?-1:1)*dt*25;a.y=clamp(a.y+d,379,510);b.y=clamp(b.y-d,379,510);}}
 for(const b of this.projectiles){b.x+=b.vx*dt;b.angle+=dt*15;b.life-=dt;for(const e of this.enemies){if(e.hp>0&&!b.hit.has(e.id)&&Math.abs(b.x-e.x)<42&&Math.abs(b.y-e.y)<33&&b.z<150){this.hurtEnemy(e,b.kind==='phone'?52:46,b.owner,37);b.hit.add(e.id);this.burst(e.x,e.y-75,b.kind==='phone'?'#cbe4df':'#e7bb65',15);if(b.hit.size>=3)b.life=0;}}}
 this.projectiles=this.projectiles.filter(b=>b.life>0);this.enemies=this.enemies.filter(e=>e.hp>0||e.dead>0);
 for(const item of this.pickups){item.life-=dt;for(const p of alive){if(Math.abs(p.x-item.x)<32&&Math.abs(p.y-item.y)<25){if(item.kind==='sandwich'){p.hp=clamp(p.hp+40,0,p.maxHp);this.emit('pickup',{name:'+40 HEALTH'});}else{this.score+=400;this.emit('pickup',{name:'+$400'});}item.life=0;break;}}}this.pickups=this.pickups.filter(i=>i.life>0);
 for(const q of this.particles){q.x+=q.vx*dt;q.y+=q.vy*dt;q.vy+=450*dt;q.life-=dt;}this.particles=this.particles.filter(q=>q.life>0);
 if(alive.length){const center=alive.reduce((s,p)=>s+p.x,0)/alive.length;this.camera+=(clamp(center-400,this.sector*800,this.sector*800+80)-this.camera)*Math.min(1,dt*5);}
 if(this.players.every(p=>p.hp<=0&&p.lives===0)){this.phase='gameover';this.emit('gameover');return;}
 if(!this.enemies.some(e=>e.hp>0)){if(this.sector===2){this.score+=2500+this.players.reduce((s,p)=>s+Math.ceil(p.hp)*10,0);this.phase=this.stage===2?'victory':'stageclear';this.emit(this.phase);return;}this.clear=true;if(alive.some(p=>p.x>this.sector*800+840)){this.sector++;for(const p of this.players){p.x=Math.max(p.x,this.sector*800+70);p.energy=clamp(p.energy+20,0,100);}this.pickups=[];this.spawnWave();}}
 }
 snapshot(){return {phase:this.phase,stage:this.stage,sector:this.sector,score:this.score,kills:this.kills,players:this.players.map(p=>({character:CREW[p.crew].name,hp:p.hp,lives:p.lives,energy:p.energy,x:p.x,y:p.y,combo:p.combo})),enemies:this.enemies.map(e=>({name:e.name,hp:e.hp,x:e.x,y:e.y})),projectiles:this.projectiles.map(p=>({kind:p.kind,x:p.x})),clear:this.clear};}
}
